import { GameScene } from "../GameScene";

var raycaster: any;
var ray: any;
var graphics: any;
var obstacles: any;
var intersections: any;

export class Raycaster {
  constructor(scene: GameScene) {
    raycaster = scene.raycasterPlugin.createRaycaster();
    ray = raycaster.createRay({
      origin: {
        x: 350,
        y: 350,
      },
    });

    obstacles = scene.add.group();
    createObstacles(scene);

    raycaster.mapGameObjects(obstacles.getChildren());
    intersections = ray.castCircle();
    graphics = scene.add.graphics({
      lineStyle: { width: 1, color: 0x00ff00 },
      fillStyle: { color: 0xffffff, alpha: 0.1 },
    });

    draw();

    //redraw on mouse move
    scene.input.on("pointermove", function (pointer: any) {
      //set ray position
      ray.setOrigin(pointer.x, pointer.y);
      console.log(pointer.x, pointer.y);

      //cast ray in all directions
      intersections = ray.castCircle();
      //redraw
      draw();
    });
  }
}

function createObstacles(scene: GameScene) {
  //create rectangle obstacle
  let obstacle: any = scene.add
    .rectangle(365, 300, 16, 16)
    .setStrokeStyle(1, 0xffff00);
  obstacles.add(obstacle, true);

  obstacle = scene.add.rectangle(460, 370, 16, 16).setStrokeStyle(1, 0xffff00);
  obstacles.add(obstacle, true);

  obstacle = scene.add.rectangle(335, 420, 24, 16).setStrokeStyle(1, 0xffff00);
  obstacles.add(obstacle, true);
}

function draw() {
  graphics.clear();
  graphics.fillStyle(0xffffff, 0.3);
  graphics.fillPoints(intersections);
  for (let intersection of intersections) {
    graphics.strokeLineShape({
      x1: ray.origin.x,
      y1: ray.origin.y,
      x2: intersection.x,
      y2: intersection.y,
    });
  }
  graphics.fillStyle(0xff00ff);
  graphics.fillPoint(ray.origin.x, ray.origin.y, 3);
}
